public record Book(string Isbn, string Title, string Author);

public abstract class Member(string id, string name)
{
    public string Id { get; } = id;
    public string Name { get; } = name;
    public decimal FinesOwed { get; internal set; }
    public abstract int MaxLoans { get; }
    public abstract int LoanDays { get; }
    public virtual decimal FinePerDay => 0.25m;
}

public class Adult(string id, string name) : Member(id, name)
{
    public override int MaxLoans => 5;
    public override int LoanDays => 21;
}

public class Child(string id, string name) : Member(id, name)
{
    public override int MaxLoans => 3;
    public override int LoanDays => 14;
    public override decimal FinePerDay => 0.10m;
}

public record Loan(Member Member, Book Book, DateOnly Due);

public class Library
{
    private const decimal MaxFine = 10.00m;
    private readonly Dictionary<string, (Book Book, int Copies)> _books = new();
    private readonly Dictionary<string, Member> _members = new();
    private readonly List<Loan> _loans = new();

    public void AddBook(Book book, int copies = 1)
    {
        if (copies < 1) throw new ArgumentOutOfRangeException(nameof(copies));
        int have = _books.TryGetValue(book.Isbn, out var entry) ? entry.Copies : 0;
        _books[book.Isbn] = (book, have + copies);
    }

    public void AddMember(Member member)
    {
        if (!_members.TryAdd(member.Id, member)) throw new ArgumentException($"member id {member.Id} is in use");
    }

    public int Available(string isbn) =>
        _books.TryGetValue(isbn, out var entry) ? entry.Copies - _loans.Count(l => l.Book.Isbn == isbn) : 0;

    public IReadOnlyList<Loan> LoansOf(string memberId) =>
        _loans.Where(l => l.Member.Id == memberId).ToList().AsReadOnly();

    public Loan Borrow(string memberId, string isbn, DateOnly today)
    {
        if (!_members.TryGetValue(memberId, out var member)) throw new InvalidOperationException($"unknown member {memberId}");
        if (!_books.TryGetValue(isbn, out var entry)) throw new InvalidOperationException($"unknown book {isbn}");
        if (member.FinesOwed > 0) throw new InvalidOperationException("unpaid fines");
        var mine = LoansOf(memberId);
        if (mine.Count >= member.MaxLoans) throw new InvalidOperationException("loan limit reached");
        if (mine.Any(l => l.Book.Isbn == isbn)) throw new InvalidOperationException("already borrowed");
        if (Available(isbn) <= 0) throw new InvalidOperationException("no copies available");
        var loan = new Loan(member, entry.Book, today.AddDays(member.LoanDays));
        _loans.Add(loan);
        return loan;
    }

    public decimal Return(string memberId, string isbn, DateOnly today)
    {
        var loan = _loans.FirstOrDefault(l => l.Member.Id == memberId && l.Book.Isbn == isbn)
                   ?? throw new InvalidOperationException("no such loan");
        _loans.Remove(loan);
        int late = Math.Max(0, today.DayNumber - loan.Due.DayNumber);
        decimal fine = Math.Min(MaxFine, late * loan.Member.FinePerDay);
        loan.Member.FinesOwed += fine;
        return fine;
    }

    public List<string> Overdue(DateOnly today) =>
        _loans.Select(l => (Loan: l, Days: today.DayNumber - l.Due.DayNumber))
              .Where(x => x.Days > 0)
              .OrderByDescending(x => x.Days)
              .ThenBy(x => x.Loan.Member.Name, StringComparer.Ordinal)
              .ThenBy(x => x.Loan.Book.Title, StringComparer.Ordinal)
              .Select(x => $"{x.Loan.Member.Name}: {x.Loan.Book.Title} ({x.Days} {(x.Days == 1 ? "day" : "days")})")
              .ToList();

    public void PayFine(string memberId, decimal amount)
    {
        if (!_members.TryGetValue(memberId, out var member)) throw new InvalidOperationException($"unknown member {memberId}");
        if (amount <= 0 || amount > member.FinesOwed) throw new ArgumentOutOfRangeException(nameof(amount));
        member.FinesOwed -= amount;
    }
}

unitTests:
var d = new DateOnly(2026, 3, 1);
var dune = new Book("111", "Dune", "Herbert");
var emma = new Book("222", "Emma", "Austen");
var ulysses = new Book("333", "Ulysses", "Joyce");

Library Setup()
{
    var lib = new Library();
    lib.AddBook(dune, 2);
    lib.AddBook(emma);
    lib.AddBook(ulysses);
    lib.AddMember(new Adult("a1", "Ada"));
    lib.AddMember(new Child("c1", "Cy"));
    return lib;
}

string ErrorOf(Action a)
{
    try { a(); return "no error"; }
    catch (InvalidOperationException e) { return e.Message; }
}

Test("borrowing", () =>
{
    var lib = Setup();
    var loan = lib.Borrow("a1", "111", d);
    CheckEq(loan.Due, new DateOnly(2026, 3, 22));
    CheckEq(loan.Book, dune);
    CheckEq(lib.Available("111"), 1);
    CheckEq(lib.Borrow("c1", "111", d).Due, new DateOnly(2026, 3, 15));
    CheckEq(lib.Available("111"), 0);
    CheckEq(lib.LoansOf("a1").Count, 1);
    CheckEq(lib.Available("999"), 0);
});

Test("borrowing errors in order", () =>
{
    var lib = Setup();
    CheckEq(ErrorOf(() => lib.Borrow("zz", "999", d)), "unknown member zz");
    CheckEq(ErrorOf(() => lib.Borrow("a1", "999", d)), "unknown book 999");
    lib.Borrow("a1", "222", d);
    CheckEq(ErrorOf(() => lib.Borrow("c1", "222", d)), "no copies available");
    CheckEq(ErrorOf(() => lib.Borrow("a1", "222", d)), "already borrowed");
    lib.AddBook(new Book("444", "A", "x"));
    lib.AddBook(new Book("555", "B", "x"));
    lib.Borrow("c1", "111", d);
    lib.Borrow("c1", "444", d);
    lib.Borrow("c1", "555", d);
    CheckEq(ErrorOf(() => lib.Borrow("c1", "333", d)), "loan limit reached");
});

Test("returning and fines", () =>
{
    var lib = Setup();
    lib.Borrow("a1", "111", d);
    lib.Borrow("c1", "222", d);
    CheckEq(lib.Return("a1", "111", d.AddDays(21)), 0m);
    CheckEq(lib.Return("c1", "222", d.AddDays(14 + 5)), 0.50m);
    CheckEq(ErrorOf(() => lib.Return("c1", "222", d)), "no such loan");
    CheckEq(lib.Available("222"), 1);
    lib.Borrow("a1", "333", d);
    CheckEq(lib.Return("a1", "333", d.AddDays(21 + 100)), 10.00m);
});

Test("fines block borrowing until paid", () =>
{
    var lib = Setup();
    var cy = new Child("c2", "Cyd");
    lib.AddMember(cy);
    lib.Borrow("c2", "111", d);
    lib.Return("c2", "111", d.AddDays(20));
    CheckEq(cy.FinesOwed, 0.60m);
    CheckEq(ErrorOf(() => lib.Borrow("c2", "222", d)), "unpaid fines");
    CheckThrows<ArgumentOutOfRangeException>(() => lib.PayFine("c2", 1m));
    CheckThrows<ArgumentOutOfRangeException>(() => lib.PayFine("c2", 0m));
    lib.PayFine("c2", 0.50m);
    CheckEq(cy.FinesOwed, 0.10m);
    lib.PayFine("c2", 0.10m);
    CheckEq(lib.Borrow("c2", "222", d).Book.Title, "Emma");
});

Test("overdue report", () =>
{
    var lib = Setup();
    lib.Borrow("a1", "111", d);
    lib.Borrow("a1", "222", d);
    lib.Borrow("c1", "333", d);
    lib.Borrow("c1", "111", d.AddDays(7));
    CheckEq(lib.Overdue(d.AddDays(22)), new[] { "Cy: Ulysses (8 days)", "Ada: Dune (1 day)", "Ada: Emma (1 day)", "Cy: Dune (1 day)" });
    CheckEq(lib.Overdue(d).Count, 0);
});

Test("setup rules", () =>
{
    var lib = Setup();
    CheckThrows<ArgumentException>(() => lib.AddMember(new Adult("a1", "Other")));
    CheckThrows<ArgumentOutOfRangeException>(() => lib.AddBook(dune, 0));
    lib.AddBook(dune);
    CheckEq(lib.Available("111"), 3);
    Check(lib.LoansOf("a1") is not List<Loan>, "LoansOf should be read-only");
    Member m = new Child("x", "X");
    CheckEq((m.MaxLoans, m.LoanDays, m.FinePerDay), (3, 14, 0.10m));
});

